    // ── 2. NatStar CompareToFinite 全序（§3.1.5a） ──────────────────────
    [Fact]
    public void NatStar_RandomTotalOrder() // §3.1.5a compare 符号相反（1000 组）
    {
        for (int i = 0; i < 1000; i++)
