            var x = RandScope();
            var y = RandScope();

            // 自反：x ⊆ x
            Assert.True(x.IncludedIn(x));
            // Global 最大元：任意 x ⊆ Global
            Assert.True(x.IncludedIn(new ScopeId.Global()));
