        if (form == 1) // [⊤,⊤]
        {
            return new Interval(NatStar.Top, NatStar.Top);
        }
        // [x,y] 且 lo<=hi
        var a = (ulong)Rng.Next(0, 500);
        var b = (ulong)Rng.Next(0, 500);
